function valutaCompatibilita(caiScale, lunghezza, dislivello, utente) {
  const scala = caiScale?.toUpperCase()?.trim();
  if (scala === "EEA" || scala === "F") {
    return {
      livello: "ferrata",
      titolo: "Ferrata / Alpinistico",
      icona: "\u26CF\uFE0F",
      messaggio: "Richiede attrezzatura specifica (casco, imbrago, dissipatore). Non affrontarlo senza esperienza."
    };
  }
  const livReq = scala ? TrailConfig.requisitiCai[scala] : null;
  if (!livReq) {
    return {
      livello: "sconosciuto",
      titolo: "Difficolt\xE0 non classificata",
      icona: "\u2753",
      messaggio: "Non ci sono informazioni sulla difficolt\xE0. Verifica prima di partire."
    };
  }
  const livUtente = utente.livelloEsperienzaMontagna;
  if (livUtente < livReq) {
    return {
      livello: "sconsigliato",
      titolo: "Non consigliato per il tuo profilo",
      icona: "\u26A0\uFE0F",
      messaggio: `Questo sentiero richiede livello ${livReq}/5, il tuo \xE8 ${livUtente}/5. Allenati su percorsi pi\xF9 semplici.`
    };
  }
  const avvertenze = [];
  if ((lunghezza ?? 0) > TrailConfig.avvertenze.lunghezzaKm)
    avvertenze.push(`percorso lungo (>${TrailConfig.avvertenze.lunghezzaKm} km): porta acqua`);
  if ((dislivello ?? 0) > TrailConfig.avvertenze.dislivelloM)
    avvertenze.push(`dislivello elevato (${dislivello} m D+): calcola i tempi`);
  if (avvertenze.length > 0) {
    return {
      livello: "fattibile",
      titolo: "Fattibile con attenzione",
      icona: "\u{1F7E1}",
      messaggio: `Il tuo livello \xE8 adatto, ma attenzione: ${avvertenze.join("; ")}.`
    };
  }
  return {
    livello: "consigliato",
    titolo: "Adatto al tuo profilo",
    icona: "\u2705",
    messaggio: `Sentiero adatto al tuo livello di esperienza (${livUtente}/5). Buona escursione!`
  };
}

